package com.example.shop.orders;

import java.util.List;

import com.example.shop.common.ConflictException;
import com.example.shop.common.NotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public OrderDto create(CreateOrderRequest request) {
        Order order = new Order(
                request.customerEmail().trim().toLowerCase(),
                request.productSku(),
                request.quantity(),
                request.unitPrice());
        return OrderDto.from(orderRepository.save(order));
    }

    public OrderDto get(Long id) {
        return orderRepository.findById(id)
                .map(OrderDto::from)
                .orElseThrow(() -> new NotFoundException("Order " + id + " not found"));
    }

    public List<OrderDto> findByCustomer(String customerEmail) {
        return orderRepository.findByCustomerEmailOrderByCreatedAtDesc(customerEmail.trim().toLowerCase())
                .stream()
                .map(OrderDto::from)
                .toList();
    }

    @Transactional
    public OrderDto cancel(Long id) {
        Order order = orderRepository.findById(id)
                .orElseThrow(() -> new NotFoundException("Order " + id + " not found"));
        if (order.getStatus() == OrderStatus.SHIPPED) {
            throw new ConflictException("Order " + id + " has already shipped");
        }
        order.cancel();
        return OrderDto.from(order);
    }
}

