package com.example.shop.orders;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.math.BigDecimal;
import java.time.Instant;

import com.example.shop.common.ConflictException;
import com.example.shop.common.NotFoundException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    private static OrderDto sampleOrder() {
        return new OrderDto(42L, "ana@example.com", "SKU-100", 2,
                new BigDecimal("9.99"), new BigDecimal("19.98"), OrderStatus.PENDING,
                Instant.parse("2024-05-01T10:15:30Z"));
    }

    @Test
    void createsOrder() throws Exception {
        given(orderService.create(any(CreateOrderRequest.class))).willReturn(sampleOrder());

        mockMvc.perform(post("/api/orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"customerEmail":"ana@example.com","productSku":"SKU-100","quantity":2,"unitPrice":9.99}
                                """))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "/api/orders/42"))
                .andExpect(jsonPath("$.id").value(42))
                .andExpect(jsonPath("$.total").value(19.98))
                .andExpect(jsonPath("$.status").value("PENDING"));
    }

    @Test
    void rejectsInvalidOrderWithProblemDetail() throws Exception {
        mockMvc.perform(post("/api/orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"customerEmail":"not-an-email","productSku":"","quantity":0,"unitPrice":9.99}
                                """))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.title").value("Invalid request"))
                .andExpect(jsonPath("$.errors.customerEmail").exists())
                .andExpect(jsonPath("$.errors.productSku").exists())
                .andExpect(jsonPath("$.errors.quantity").exists());

        verify(orderService, never()).create(any());
    }

    @Test
    void returnsNotFoundProblem() throws Exception {
        given(orderService.get(7L)).willThrow(new NotFoundException("Order 7 not found"));

        mockMvc.perform(get("/api/orders/7"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").value("Order 7 not found"));
    }

    @Test
    void returnsConflictWhenCancellingShippedOrder() throws Exception {
        given(orderService.cancel(42L)).willThrow(new ConflictException("Order 42 has already shipped"));

        mockMvc.perform(post("/api/orders/42/cancel"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.title").value("Conflict"));
    }
}

package com.example.shop.orders;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;

import java.math.BigDecimal;
import java.util.Optional;

import com.example.shop.common.NotFoundException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    void normalisesEmailAndComputesTotal() {
        given(orderRepository.save(any(Order.class))).willAnswer(invocation -> invocation.getArgument(0));

        OrderDto created = orderService.create(
                new CreateOrderRequest("  Ana@Example.com ", "SKU-100", 3, new BigDecimal("2.50")));

        ArgumentCaptor<Order> saved = ArgumentCaptor.forClass(Order.class);
        verify(orderRepository).save(saved.capture());
        assertThat(saved.getValue().getCustomerEmail()).isEqualTo("ana@example.com");
        assertThat(created.total()).isEqualByComparingTo("7.50");
        assertThat(created.status()).isEqualTo(OrderStatus.PENDING);
    }

    @Test
    void throwsWhenOrderMissing() {
        given(orderRepository.findById(99L)).willReturn(Optional.empty());

        assertThatThrownBy(() -> orderService.get(99L))
                .isInstanceOf(NotFoundException.class)
                .hasMessageContaining("99");
    }
}

