const (
	defaultLimit = 20
	maxLimit     = 100
)

type ProductHandler struct{ svc *service.ProductService }

func NewProductHandler(s *service.ProductService) *ProductHandler { return &ProductHandler{svc: s} }

func (h *ProductHandler) Register(r *gin.Engine) {
	r.GET("/products", h.list)
}

// parsePage reads ?limit= and ?cursor= (opaque keyset cursor).
func parsePage(c *gin.Context) (service.Page, error) {
	limit := defaultLimit
	if v := c.Query("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > maxLimit {
			return service.Page{}, fmt.Errorf("%w: limit must be 1..%d", service.ErrInvalidInput, maxLimit)
		}
		limit = n
	}
	return service.Page{Limit: limit, Cursor: c.Query("cursor")}, nil
}

func (h *ProductHandler) list(c *gin.Context) {
	page, err := parsePage(c)
	if err != nil {
		writeError(c, err)
		return
	}
	items, next, err := h.svc.List(c.Request.Context(), page)
	if err != nil {
		writeError(c, err)
		return
	}
	writeJSON(c, http.StatusOK, items, pageMeta{NextCursor: next, Limit: page.Limit})
}

