func TestParsePage(t *testing.T) {
	gin.SetMode(gin.TestMode)
	tests := []struct {
		name    string
		query   string
		wantErr bool
		limit   int
	}{
		{"default", "", false, defaultLimit},
		{"valid", "?limit=5", false, 5},
		{"zero", "?limit=0", true, 0},
		{"too big", "?limit=101", true, 0},
		{"not a number", "?limit=x", true, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c, _ := gin.CreateTestContext(httptest.NewRecorder())
			c.Request = httptest.NewRequest(http.MethodGet, "/products"+tt.query, nil)
			p, err := parsePage(c)
			if tt.wantErr {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tt.limit, p.Limit)
		})
	}
}

