import { db } from '../db';

export type AccountStatus = 'active' | 'suspended' | 'closed';

export interface Account {
  id: number;
  email: string;
  name: string;
  status: AccountStatus;
  plan: string;
  createdAt: Date;
  updatedAt: Date;
}

interface AccountRow {
  id: number;
  email: string;
  name: string;
  status: AccountStatus;
  plan: string;
  created_at: Date;
  updated_at: Date;
}

export interface NewAccount {
  email: string;
  name: string;
  plan: string;
}

export interface AccountChanges {
  name?: string;
  status?: AccountStatus;
  plan?: string;
}

function toAccount(row: AccountRow): Account {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    status: row.status,
    plan: row.plan,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export const accountRepository = {
  async findAll(limit: number, offset: number): Promise<Account[]> {
    const rows = await db<AccountRow>('accounts').orderBy('id', 'asc').limit(limit).offset(offset);
    return rows.map(toAccount);
  },

  async findById(id: number): Promise<Account | undefined> {
    const row = await db<AccountRow>('accounts').where({ id }).first();
    return row ? toAccount(row) : undefined;
  },

  async findByEmail(email: string): Promise<Account | undefined> {
    const row = await db<AccountRow>('accounts').where({ email }).first();
    return row ? toAccount(row) : undefined;
  },

  async create(input: NewAccount): Promise<Account> {
    const [id] = await db('accounts').insert({
      email: input.email,
      name: input.name,
      plan: input.plan,
    });
    const created = await this.findById(id);
    if (!created) {
      throw new Error(`Account ${id} missing after insert`);
    }
    return created;
  },

  async update(id: number, changes: AccountChanges): Promise<Account | undefined> {
    await db('accounts')
      .where({ id })
      .update({ ...changes, updated_at: db.fn.now() });
    return this.findById(id);
  },
};

