  '/:id',
  asyncHandler(async (req, res) => {
    const account = await accountService.get(parseId(req.params.id));
    res.json({ data: account });
  }),
);

accountsRouter.post(
  '/',
  asyncHandler(async (req, res) => {
    const account = await accountService.create(req.body);
    res.status(201).json({ data: account });
  }),
);

