import { ConflictError, NotFoundError, ValidationError } from '../errors';
import {
  Account,
  AccountChanges,
  AccountStatus,
  NewAccount,
  accountRepository,
} from '../repositories/accountRepository';

const STATUSES: readonly AccountStatus[] = ['active', 'suspended', 'closed'];
const PLANS = ['free', 'team', 'enterprise'];
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function requireName(value: unknown): string {
  if (typeof value !== 'string' || value.trim().length === 0 || value.length > 120) {
    throw new ValidationError('name must be a non-empty string of at most 120 characters');
  }
  return value.trim();
}

function requirePlan(value: unknown): string {
  if (typeof value !== 'string' || !PLANS.includes(value)) {
    throw new ValidationError(`plan must be one of: ${PLANS.join(', ')}`);
  }
  return value;
}

function parseNewAccount(input: unknown): NewAccount {
  if (!isRecord(input)) {
    throw new ValidationError('Request body must be a JSON object');
  }
  const { email, name, plan = 'free' } = input;
  if (typeof email !== 'string' || !EMAIL_PATTERN.test(email)) {
    throw new ValidationError('email must be a valid email address');
  }
  return { email: email.toLowerCase(), name: requireName(name), plan: requirePlan(plan) };
}

function parseChanges(input: unknown): AccountChanges {
  if (!isRecord(input)) {
    throw new ValidationError('Request body must be a JSON object');
  }
  const changes: AccountChanges = {};
  if ('name' in input) changes.name = requireName(input.name);
  if ('plan' in input) changes.plan = requirePlan(input.plan);
  if ('status' in input) {
    if (!STATUSES.includes(input.status as AccountStatus)) {
      throw new ValidationError(`status must be one of: ${STATUSES.join(', ')}`);
    }
    changes.status = input.status as AccountStatus;
  }
  if (Object.keys(changes).length === 0) {
    throw new ValidationError('At least one of name, plan or status is required');
  }
  return changes;
}

export const accountService = {
  list(limit: number, offset: number): Promise<Account[]> {
    return accountRepository.findAll(limit, offset);
  },

  async get(id: number): Promise<Account> {
    const account = await accountRepository.findById(id);
    if (!account) {
      throw new NotFoundError(`Account ${id} not found`);
    }
    return account;
  },

  async create(input: unknown): Promise<Account> {
    const data = parseNewAccount(input);
    if (await accountRepository.findByEmail(data.email)) {
      throw new ConflictError(`An account with email ${data.email} already exists`);
    }
    return accountRepository.create(data);
  },

  async update(id: number, input: unknown): Promise<Account> {
    const changes = parseChanges(input);
    const existing = await accountRepository.findById(id);
    if (!existing) {
      throw new NotFoundError(`Account ${id} not found`);
    }
    if (existing.status === 'closed') {
      throw new ConflictError(`Account ${id} is closed and cannot be modified`);
    }
    const updated = await accountRepository.update(id, changes);
    if (!updated) {
      throw new NotFoundError(`Account ${id} not found`);
    }
    return updated;
  },
};

