import { ValidationError } from '../errors';

export function parseId(raw: string): number {
  const id = Number(raw);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(`Invalid id: ${raw}`);
  }
  return id;
}

export function parseLimit(raw: unknown, fallback = 20, max = 100): number {
  if (raw === undefined) return fallback;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 1 || value > max) {
    throw new ValidationError(`limit must be an integer between 1 and ${max}`);
  }
  return value;
}

export function parseOffset(raw: unknown): number {
  if (raw === undefined) return 0;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 0) {
    throw new ValidationError('offset must be a non-negative integer');
  }
  return value;
}

