import request from 'supertest';
import { createApp } from '../src/app';
import { Account, accountRepository } from '../src/repositories/accountRepository';

jest.mock('../src/repositories/accountRepository');

const repo = jest.mocked(accountRepository);
const app = createApp();

function makeAccount(overrides: Partial<Account> = {}): Account {
  return {
    id: 1,
    email: 'jane@example.com',
    name: 'Jane Doe',
    status: 'active',
    plan: 'free',
    createdAt: new Date('2024-03-01T10:00:00Z'),
    updatedAt: new Date('2024-03-01T10:00:00Z'),
    ...overrides,
  };
}

describe('GET /accounts', () => {
  it('returns a page of accounts', async () => {
    repo.findAll.mockResolvedValue([makeAccount(), makeAccount({ id: 2, email: 'sam@example.com' })]);

    const res = await request(app).get('/accounts?limit=2');

    expect(res.status).toBe(200);
    expect(res.body.data).toHaveLength(2);
    expect(res.body).toMatchObject({ limit: 2, offset: 0 });
    expect(repo.findAll).toHaveBeenCalledWith(2, 0);
  });

  it('rejects an out-of-range limit', async () => {
    const res = await request(app).get('/accounts?limit=500');

    expect(res.status).toBe(400);
    expect(res.body).toEqual({
      error: { code: 'VALIDATION_ERROR', message: 'limit must be an integer between 1 and 100' },
    });
  });
});

describe('GET /accounts/:id', () => {
  it('returns the account', async () => {
    repo.findById.mockResolvedValue(makeAccount({ id: 7 }));

    const res = await request(app).get('/accounts/7');

    expect(res.status).toBe(200);
    expect(res.body.data).toMatchObject({ id: 7, email: 'jane@example.com' });
  });

  it('returns 404 in the standard error format', async () => {
    repo.findById.mockResolvedValue(undefined);

    const res = await request(app).get('/accounts/999');

    expect(res.status).toBe(404);
    expect(res.body).toEqual({ error: { code: 'NOT_FOUND', message: 'Account 999 not found' } });
  });

  it('returns 400 for a non-numeric id', async () => {
    const res = await request(app).get('/accounts/abc');

    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('VALIDATION_ERROR');
  });
});

describe('POST /accounts', () => {
  it('creates an account', async () => {
    repo.findByEmail.mockResolvedValue(undefined);
    repo.create.mockResolvedValue(makeAccount({ id: 3, email: 'new@example.com', name: 'New User' }));

    const res = await request(app)
      .post('/accounts')
      .send({ email: 'New@Example.com', name: 'New User' });

    expect(res.status).toBe(201);
    expect(res.body.data.id).toBe(3);
    expect(repo.create).toHaveBeenCalledWith({ email: 'new@example.com', name: 'New User', plan: 'free' });
  });

  it('rejects an invalid email', async () => {
    const res = await request(app).post('/accounts').send({ email: 'nope', name: 'X' });

    expect(res.status).toBe(400);
    expect(res.body).toEqual({
      error: { code: 'VALIDATION_ERROR', message: 'email must be a valid email address' },
    });
    expect(repo.create).not.toHaveBeenCalled();
  });

  it('returns 409 when the email is taken', async () => {
    repo.findByEmail.mockResolvedValue(makeAccount());

    const res = await request(app).post('/accounts').send({ email: 'jane@example.com', name: 'Jane' });

    expect(res.status).toBe(409);
    expect(res.body.error.code).toBe('CONFLICT');
  });
});

