using Microsoft.AspNetCore.Http.HttpResults;
using Shop.Application.Customers;

namespace Shop.Api.Customers;

public static class CustomerEndpoints
{
    public static RouteGroupBuilder MapCustomerEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/customers").WithTags("Customers");

        group.MapGet("/", ListCustomers).WithName("ListCustomers");
        group.MapGet("/{id:guid}", GetCustomer).WithName("GetCustomer");
        group.MapPost("/", CreateCustomer).WithName("CreateCustomer");
        group.MapPut("/{id:guid}", UpdateCustomer).WithName("UpdateCustomer");

        return group;
    }

    private static async Task<Ok<IReadOnlyList<CustomerResponse>>> ListCustomers(
        CustomerService service,
        CancellationToken cancellationToken)
    {
        var customers = await service.ListAsync(cancellationToken);
        IReadOnlyList<CustomerResponse> response = customers.Select(CustomerResponse.From).ToList();
        return TypedResults.Ok(response);
    }

    private static async Task<Ok<CustomerResponse>> GetCustomer(
        Guid id,
        CustomerService service,
        CancellationToken cancellationToken)
    {
        var customer = await service.GetAsync(id, cancellationToken);
        return TypedResults.Ok(CustomerResponse.From(customer));
    }

    private static async Task<CreatedAtRoute<CustomerResponse>> CreateCustomer(
        CreateCustomerRequest request,
        CustomerService service,
        CancellationToken cancellationToken)
    {
        var customer = await service.CreateAsync(
            new CreateCustomerCommand(request.Name, request.Email),
            cancellationToken);

        return TypedResults.CreatedAtRoute(
            CustomerResponse.From(customer),
            "GetCustomer",
            new { id = customer.Id });
    }

    private static async Task<Ok<CustomerResponse>> UpdateCustomer(
        Guid id,
        UpdateCustomerRequest request,
        CustomerService service,
        CancellationToken cancellationToken)
    {
        var customer = await service.UpdateAsync(
            id,
            new UpdateCustomerCommand(request.Name, request.Email),
            cancellationToken);

        return TypedResults.Ok(CustomerResponse.From(customer));
    }
}

