using System.Net.Mail;
using Shop.Application.Common;

namespace Shop.Application.Customers;

public sealed class CustomerService(ICustomerRepository repository, TimeProvider timeProvider)
{
    public const int NameMaxLength = 200;
    public const int EmailMaxLength = 320;

    public async Task<IReadOnlyList<CustomerDto>> ListAsync(CancellationToken cancellationToken)
    {
        var customers = await repository.ListAsync(cancellationToken);
        return customers.Select(CustomerDto.From).ToList();
    }

    public async Task<CustomerDto> GetAsync(Guid id, CancellationToken cancellationToken)
    {
        var customer = await repository.FindAsync(id, cancellationToken)
            ?? throw new NotFoundException($"Customer '{id}' was not found.");
        return CustomerDto.From(customer);
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerCommand command, CancellationToken cancellationToken)
    {
        Validate(command.Name, command.Email);

        var name = command.Name.Trim();
        var email = NormalizeEmail(command.Email);

        if (await repository.EmailExistsAsync(email, excludingId: null, cancellationToken))
        {
            throw new ConflictException($"A customer with email '{email}' already exists.");
        }

        var customer = Customer.Create(name, email, timeProvider.GetUtcNow());
        repository.Add(customer);
        await repository.SaveChangesAsync(cancellationToken);

        return CustomerDto.From(customer);
    }

    public async Task<CustomerDto> UpdateAsync(Guid id, UpdateCustomerCommand command, CancellationToken cancellationToken)
    {
        Validate(command.Name, command.Email);

        var customer = await repository.FindAsync(id, cancellationToken)
            ?? throw new NotFoundException($"Customer '{id}' was not found.");

        var email = NormalizeEmail(command.Email);
        if (await repository.EmailExistsAsync(email, excludingId: id, cancellationToken))
        {
            throw new ConflictException($"A customer with email '{email}' already exists.");
        }

        customer.Update(command.Name.Trim(), email);
        await repository.SaveChangesAsync(cancellationToken);

        return CustomerDto.From(customer);
    }

    private static string NormalizeEmail(string email) => email.Trim().ToLowerInvariant();

    private static void Validate(string? name, string? email)
    {
        var errors = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(name))
        {
            errors["name"] = ["Name is required."];
        }
        else if (name.Trim().Length > NameMaxLength)
        {
            errors["name"] = [$"Name must be at most {NameMaxLength} characters."];
        }

        if (string.IsNullOrWhiteSpace(email))
        {
            errors["email"] = ["Email is required."];
        }
        else if (email.Trim().Length > EmailMaxLength || !MailAddress.TryCreate(email.Trim(), out _))
        {
            errors["email"] = ["Email must be a valid email address."];
        }

        if (errors.Count > 0)
        {
            throw new RequestValidationException(errors);
        }
    }
}

