internal sealed class CustomerRepository(ShopDbContext dbContext) : ICustomerRepository
{
    public async Task<IReadOnlyList<Customer>> ListAsync(CancellationToken cancellationToken) =>
        await dbContext.Customers
            .AsNoTracking()
            .OrderBy(c => c.Name)
            .ToListAsync(cancellationToken);

    public Task<Customer?> FindAsync(Guid id, CancellationToken cancellationToken) =>
        dbContext.Customers.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);

    public Task<bool> EmailExistsAsync(string email, Guid? excludingId, CancellationToken cancellationToken) =>
        dbContext.Customers.AnyAsync(
            c => c.Email == email && (excludingId == null || c.Id != excludingId),
            cancellationToken);

    public void Add(Customer customer) => dbContext.Customers.Add(customer);

    public Task SaveChangesAsync(CancellationToken cancellationToken) => dbContext.SaveChangesAsync(cancellationToken);
}

