using System.Net;
using System.Net.Http.Json;
using FluentAssertions;
using Microsoft.AspNetCore.Mvc;
using Shop.Api.Customers;

namespace Shop.Api.Tests;

public sealed class CustomerEndpointsTests(ShopApiFactory factory) : IClassFixture<ShopApiFactory>
{
    private readonly HttpClient _client = factory.CreateClient();

    private static string UniqueEmail() => $"customer-{Guid.NewGuid():N}@example.com";

    [Fact]
    public async Task Create_returns_201_with_location_and_body()
    {
        var email = UniqueEmail();

        var response = await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("Ana Lopez", email));

        response.StatusCode.Should().Be(HttpStatusCode.Created);
        response.Headers.Location.Should().NotBeNull();

        var body = await response.Content.ReadFromJsonAsync<CustomerResponse>();
        body.Should().NotBeNull();
        body!.Name.Should().Be("Ana Lopez");
        body.Email.Should().Be(email);
        body.Id.Should().NotBeEmpty();
    }

    [Fact]
    public async Task Create_with_invalid_payload_returns_validation_problem()
    {
        var response = await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("", "not-an-email"));

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
        response.Content.Headers.ContentType!.MediaType.Should().Be("application/problem+json");

        var problem = await response.Content.ReadFromJsonAsync<ValidationProblemDetails>();
        problem!.Errors.Should().ContainKeys("name", "email");
    }

    [Fact]
    public async Task Create_with_duplicate_email_returns_409()
    {
        var email = UniqueEmail();
        (await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("First", email)))
            .EnsureSuccessStatusCode();

        var response = await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("Second", email.ToUpperInvariant()));

        response.StatusCode.Should().Be(HttpStatusCode.Conflict);
        var problem = await response.Content.ReadFromJsonAsync<ProblemDetails>();
        problem!.Title.Should().Be("Conflict");
    }

    [Fact]
    public async Task Get_returns_created_customer()
    {
        var created = await (await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("Ben Ito", UniqueEmail())))
            .Content.ReadFromJsonAsync<CustomerResponse>();

        var fetched = await _client.GetFromJsonAsync<CustomerResponse>($"/api/customers/{created!.Id}");

        fetched.Should().BeEquivalentTo(created);
    }

    [Fact]
    public async Task Get_unknown_customer_returns_404_problem()
    {
        var response = await _client.GetAsync($"/api/customers/{Guid.NewGuid()}");

        response.StatusCode.Should().Be(HttpStatusCode.NotFound);
        var problem = await response.Content.ReadFromJsonAsync<ProblemDetails>();
        problem!.Status.Should().Be(404);
    }

    [Fact]
    public async Task Update_changes_name_and_email()
    {
        var created = await (await _client.PostAsJsonAsync("/api/customers", new CreateCustomerRequest("Cleo", UniqueEmail())))
            .Content.ReadFromJsonAsync<CustomerResponse>();
        var newEmail = UniqueEmail();

        var response = await _client.PutAsJsonAsync($"/api/customers/{created!.Id}", new UpdateCustomerRequest("Cleo Park", newEmail));

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        var updated = await response.Content.ReadFromJsonAsync<CustomerResponse>();
        updated!.Name.Should().Be("Cleo Park");
        updated.Email.Should().Be(newEmail);
        updated.CreatedAt.Should().Be(created.CreatedAt);
    }
}

