@RestController
@RequestMapping("/api/customers/{customerId}/orders")
class OrderController(private val orderService: OrderService) {

    @GetMapping
    @PreAuthorize("@customerAccess.isSelfOrAdmin(authentication, #customerId)")
    fun list(@PathVariable customerId: Long): List<OrderResponse> =
        orderService.findForCustomer(customerId)

    @GetMapping("/{orderId}")
    @PreAuthorize("@customerAccess.isSelfOrAdmin(authentication, #customerId)")
    fun get(@PathVariable customerId: Long, @PathVariable orderId: Long): OrderResponse =
        orderService.get(customerId, orderId)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    @PreAuthorize("@customerAccess.isSelfOrAdmin(authentication, #customerId)")
    fun place(
        @PathVariable customerId: Long,
        @Valid @RequestBody request: PlaceOrderRequest,
    ): OrderResponse = orderService.place(customerId, request)
}

package com.example.shop.orders

import org.springframework.data.jpa.repository.EntityGraph
import org.springframework.data.jpa.repository.JpaRepository

interface OrderRepository : JpaRepository<Order, Long> {

    @EntityGraph(attributePaths = ["lines", "lines.product"])
    fun findAllByCustomerIdOrderByCreatedAtDesc(customerId: Long): List<Order>

    @EntityGraph(attributePaths = ["lines", "lines.product"])
    fun findByIdAndCustomerId(id: Long, customerId: Long): Order?
}

package com.example.shop.orders

import com.example.shop.catalog.ProductRepository
import com.example.shop.common.NotFoundException
import com.example.shop.common.UnprocessableException
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional

@Service
@Transactional(readOnly = true)
class OrderService(
    private val orderRepository: OrderRepository,
    private val productRepository: ProductRepository,
) {

    fun findForCustomer(customerId: Long): List<OrderResponse> =
        orderRepository.findAllByCustomerIdOrderByCreatedAtDesc(customerId).map { it.toResponse() }

    fun get(customerId: Long, orderId: Long): OrderResponse =
        orderRepository.findByIdAndCustomerId(orderId, customerId)?.toResponse()
            ?: throw NotFoundException("Order $orderId not found")

    @Transactional
    fun place(customerId: Long, request: PlaceOrderRequest): OrderResponse {
        val productIds = request.lines.map { it.productId }.toSet()
        val products = productRepository.findAllByIdInAndActiveTrue(productIds).associateBy { requireNotNull(it.id) }

        val unknown = productIds - products.keys
        if (unknown.isNotEmpty()) {
            throw UnprocessableException("Unknown or inactive products: ${unknown.sorted().joinToString()}")
        }

        val order = Order(customerId = customerId)
        request.lines.forEach { line -> order.addLine(products.getValue(line.productId), line.quantity) }

        return orderRepository.save(order).toResponse()
    }
}

