package com.example.shop.security

import org.springframework.security.core.Authentication
import org.springframework.security.oauth2.jwt.Jwt
import org.springframework.stereotype.Component

@Component("customerAccess")
class CustomerAccess {

    fun isSelfOrAdmin(authentication: Authentication, customerId: Long): Boolean {
        if (authentication.authorities.any { it.authority == ADMIN_AUTHORITY }) {
            return true
        }
        val jwt = authentication.principal as? Jwt ?: return false
        return jwt.getClaimAsString(CUSTOMER_ID_CLAIM) == customerId.toString()
    }

    companion object {
        const val ADMIN_AUTHORITY = "SCOPE_shop.admin"
        const val CUSTOMER_ID_CLAIM = "customer_id"
    }
}

