import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest
import org.springframework.context.annotation.Import
import org.springframework.http.MediaType
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.get
import org.springframework.test.web.servlet.post
import java.math.BigDecimal
import java.time.Instant

@WebMvcTest(OrderController::class)
@Import(SecurityConfig::class, CustomerAccess::class)
class OrderControllerTest {

    @Autowired
    private lateinit var mockMvc: MockMvc

    @MockkBean
    private lateinit var orderService: OrderService

    private fun customerToken(customerId: Long) =
        jwt().jwt { it.claim(CustomerAccess.CUSTOMER_ID_CLAIM, customerId.toString()) }

    private val order = OrderResponse(
        id = 10,
        status = OrderStatus.PLACED,
        createdAt = Instant.parse("2024-06-01T09:00:00Z"),
        total = BigDecimal("25.00"),
        lines = listOf(OrderLineResponse(1, "MUG-1", "Mug", 2, BigDecimal("12.50"))),
    )

    @Test
    fun `lists orders for the authenticated customer`() {
        every { orderService.findForCustomer(7) } returns listOf(order)

        mockMvc.get("/api/customers/7/orders") { with(customerToken(7)) }
            .andExpect {
                status { isOk() }
                jsonPath("$[0].id") { value(10) }
                jsonPath("$[0].lines[0].sku") { value("MUG-1") }
            }
    }

    @Test
    fun `forbids access to another customer's orders`() {
        mockMvc.get("/api/customers/8/orders") { with(customerToken(7)) }
            .andExpect { status { isForbidden() } }

        verify(exactly = 0) { orderService.findForCustomer(any()) }
    }

    @Test
    fun `requires authentication`() {
        mockMvc.get("/api/customers/7/orders")
            .andExpect { status { isUnauthorized() } }
    }

    @Test
    fun `rejects an empty order`() {
        mockMvc.post("/api/customers/7/orders") {
            with(customerToken(7))
            contentType = MediaType.APPLICATION_JSON
            content = """{"lines":[]}"""
        }.andExpect {
            status { isBadRequest() }
            jsonPath("$.errors.lines") { exists() }
        }
    }

    @Test
    fun `returns problem detail when order is missing`() {
        every { orderService.get(7, 99) } throws NotFoundException("Order 99 not found")

        mockMvc.get("/api/customers/7/orders/99") { with(customerToken(7)) }
            .andExpect {
                status { isNotFound() }
                content { contentType(MediaType.APPLICATION_PROBLEM_JSON) }
                jsonPath("$.detail") { value("Order 99 not found") }
            }
    }
}

