import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager
import org.springframework.context.annotation.Import
import java.math.BigDecimal

@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@Import(TestcontainersConfiguration::class)
class OrderRepositoryTest {

    @Autowired
    private lateinit var orderRepository: OrderRepository

    @Autowired
    private lateinit var productRepository: ProductRepository

    @Autowired
    private lateinit var entityManager: TestEntityManager

    @Test
    fun `loads a customer's orders with lines and products`() {
        val mug = productRepository.save(
            Product(sku = "MUG-1", name = "Mug", price = BigDecimal("12.50"), costPrice = BigDecimal("4.10")),
        )
        orderRepository.save(Order(customerId = 7).apply { addLine(mug, 2) })
        orderRepository.save(Order(customerId = 8).apply { addLine(mug, 1) })
        entityManager.flush()
        entityManager.clear()

        val orders = orderRepository.findAllByCustomerIdOrderByCreatedAtDesc(7)

        assertThat(orders).hasSize(1)
        assertThat(orders.single().lines.single().product.sku).isEqualTo("MUG-1")
        assertThat(orders.single().total()).isEqualByComparingTo("25.00")
    }

    @Test
    fun `scopes order lookup to the owning customer`() {
        val mug = productRepository.save(
            Product(sku = "MUG-2", name = "Mug", price = BigDecimal("9.00"), costPrice = BigDecimal("3.00")),
        )
        val order = orderRepository.save(Order(customerId = 7).apply { addLine(mug, 1) })
        entityManager.flush()

        assertThat(orderRepository.findByIdAndCustomerId(order.id!!, 7)).isNotNull
        assertThat(orderRepository.findByIdAndCustomerId(order.id!!, 8)).isNull()
    }
}

package com.example.shop.orders

import com.example.shop.catalog.Product
import com.example.shop.catalog.ProductRepository
import com.example.shop.common.NotFoundException
import com.example.shop.common.UnprocessableException
import io.mockk.every
import io.mockk.mockk
import io.mockk.verify
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import java.math.BigDecimal

class OrderServiceTest {

    private val orderRepository = mockk<OrderRepository>()
    private val productRepository = mockk<ProductRepository>()
    private val service = OrderService(orderRepository, productRepository)

    private fun product(id: Long, sku: String, price: String) =
        Product(sku = sku, name = "Product $sku", price = BigDecimal(price), costPrice = BigDecimal("1.00"))
            .apply { this.id = id }

    @Test
    fun `places order with a single product lookup`() {
        val mug = product(1, "MUG-1", "12.50")
        val tee = product(2, "TEE-1", "15.00")
        every { productRepository.findAllByIdInAndActiveTrue(setOf(1L, 2L)) } returns listOf(mug, tee)
        every { orderRepository.save(any()) } answers { firstArg<Order>().apply { id = 10 } }

        val response = service.place(
            customerId = 7,
            request = PlaceOrderRequest(listOf(PlaceOrderLine(1, 2), PlaceOrderLine(2, 1))),
        )

        assertThat(response.id).isEqualTo(10)
        assertThat(response.total).isEqualByComparingTo("40.00")
        assertThat(response.lines.map { it.sku }).containsExactly("MUG-1", "TEE-1")
        verify(exactly = 1) { productRepository.findAllByIdInAndActiveTrue(any()) }
    }

    @Test
    fun `rejects unknown or inactive products`() {
        every { productRepository.findAllByIdInAndActiveTrue(setOf(1L, 99L)) } returns listOf(product(1, "MUG-1", "12.50"))

        val ex = assertThrows<UnprocessableException> {
            service.place(7, PlaceOrderRequest(listOf(PlaceOrderLine(1, 1), PlaceOrderLine(99, 1))))
        }

        assertThat(ex.message).contains("99")
        verify(exactly = 0) { orderRepository.save(any()) }
    }

    @Test
    fun `does not return another customer's order`() {
        every { orderRepository.findByIdAndCustomerId(10, 8) } returns null

        assertThrows<NotFoundException> { service.get(customerId = 8, orderId = 10) }
    }
}

