package com.example.shop.wishlist

import org.jetbrains.exposed.sql.Database
import org.jetbrains.exposed.sql.ResultRow
import org.jetbrains.exposed.sql.SortOrder
import org.jetbrains.exposed.sql.SqlExpressionBuilder.eq
import org.jetbrains.exposed.sql.and
import org.jetbrains.exposed.sql.deleteWhere
import org.jetbrains.exposed.sql.insert
import org.jetbrains.exposed.sql.selectAll
import org.jetbrains.exposed.sql.transactions.transaction
import org.springframework.stereotype.Repository
import java.time.Instant

@Repository
class WishlistRepository(private val database: Database) {

    fun findByCustomerId(customerId: Long): List<WishlistItem> = transaction(database) {
        WishlistItems.selectAll()
            .where { WishlistItems.customerId eq customerId }
            .orderBy(WishlistItems.addedAt, SortOrder.DESC)
            .map { it.toWishlistItem() }
    }

    fun exists(customerId: Long, productId: Long): Boolean = transaction(database) {
        !WishlistItems.selectAll()
            .where { (WishlistItems.customerId eq customerId) and (WishlistItems.productId eq productId) }
            .empty()
    }

    fun add(customerId: Long, productId: Long): WishlistItem = transaction(database) {
        val now = Instant.now()
        val id = WishlistItems.insert {
            it[WishlistItems.customerId] = customerId
            it[WishlistItems.productId] = productId
            it[addedAt] = now
        } get WishlistItems.id
        WishlistItem(id = id, customerId = customerId, productId = productId, addedAt = now)
    }

    fun remove(customerId: Long, productId: Long): Boolean = transaction(database) {
        WishlistItems.deleteWhere {
            (WishlistItems.customerId eq customerId) and (WishlistItems.productId eq productId)
        } > 0
    }

    private fun ResultRow.toWishlistItem() = WishlistItem(
        id = this[WishlistItems.id],
        customerId = this[WishlistItems.customerId],
        productId = this[WishlistItems.productId],
        addedAt = this[WishlistItems.addedAt],
    )
}

package com.example.shop.wishlist

import com.example.shop.catalog.Product
import com.example.shop.catalog.ProductRepository
import com.example.shop.common.NotFoundException
import com.example.shop.common.UnprocessableException
import org.springframework.stereotype.Service

@Service
class WishlistService(
    private val wishlistRepository: WishlistRepository,
    private val productRepository: ProductRepository,
) {

    fun getWishlist(customerId: Long): List<Product> {
        val items = wishlistRepository.findByCustomerId(customerId)
        val products = mutableListOf<Product>()
        for (item in items) {
            productRepository.findById(item.productId).ifPresent { product ->
                if (product.active) {
                    products.add(product)
                }
            }
        }
        return products
    }

    fun addProduct(customerId: Long, productId: Long) {
        val product = productRepository.findById(productId)
            .orElseThrow { NotFoundException("Product $productId not found") }
        if (!product.active) {
            throw UnprocessableException("Product $productId is no longer available")
        }
        if (!wishlistRepository.exists(customerId, productId)) {
            wishlistRepository.add(customerId, productId)
        }
    }

    fun removeProduct(customerId: Long, productId: Long) {
        if (!wishlistRepository.remove(customerId, productId)) {
            throw NotFoundException("Product $productId is not on the wishlist")
        }
    }
}

