import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.mockito.kotlin.mock
import org.mockito.kotlin.never
import org.mockito.kotlin.verify
import org.mockito.kotlin.whenever
import java.math.BigDecimal
import java.time.Instant
import java.util.Optional

class WishlistServiceTest {

    private val wishlistRepository: WishlistRepository = mock()
    private val productRepository: ProductRepository = mock()
    private val wishlistService = WishlistService(wishlistRepository, productRepository)

    private fun product(id: Long, sku: String) =
        Product(sku = sku, name = "Product $sku", price = BigDecimal("10.00"), costPrice = BigDecimal("4.00"))
            .apply { this.id = id }

    @Test
    fun `returns the products on a customer's wishlist`() {
        whenever(wishlistRepository.findByCustomerId(7)).thenReturn(
            listOf(
                WishlistItem(1, 7, 1, Instant.parse("2024-06-02T10:00:00Z")),
                WishlistItem(2, 7, 2, Instant.parse("2024-06-01T10:00:00Z")),
            ),
        )
        whenever(productRepository.findById(1)).thenReturn(Optional.of(product(1, "MUG-1")))
        whenever(productRepository.findById(2)).thenReturn(Optional.of(product(2, "TEE-1")))

        val wishlist = wishlistService.getWishlist(7)

        assertThat(wishlist.map { it.sku }).containsExactly("MUG-1", "TEE-1")
    }

    @Test
    fun `adds a product to the wishlist`() {
        whenever(productRepository.findById(1)).thenReturn(Optional.of(product(1, "MUG-1")))
        whenever(wishlistRepository.exists(7, 1)).thenReturn(false)
        whenever(wishlistRepository.add(7, 1)).thenReturn(WishlistItem(5, 7, 1, Instant.now()))

        wishlistService.addProduct(7, 1)

        verify(wishlistRepository).add(7, 1)
    }

    @Test
    fun `does not add a product twice`() {
        whenever(productRepository.findById(1)).thenReturn(Optional.of(product(1, "MUG-1")))
        whenever(wishlistRepository.exists(7, 1)).thenReturn(true)

        wishlistService.addProduct(7, 1)

        verify(wishlistRepository, never()).add(7, 1)
    }
}

