    const moduleRef = await Test.createTestingModule({
      controllers: [CustomersController],
      providers: [{ provide: CustomersService, useValue: customersService }],
    })
      .overrideGuard(ApiKeyGuard)
      .useValue({ canActivate: () => true })
      .compile();

    app = moduleRef.createNestApplication();
    app.useGlobalPipes(new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true, transform: true }));
    await app.init();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(() => jest.clearAllMocks());

  it('GET /customers applies pagination defaults', async () => {
    customersService.findAll.mockResolvedValue({
      data: [],
      meta: { page: 1, limit: 20, total: 0, totalPages: 0 },
    });

    const res = await request(app.getHttpServer()).get('/customers').expect(200);

    expect(res.body.meta).toEqual({ page: 1, limit: 20, total: 0, totalPages: 0 });
    expect(customersService.findAll).toHaveBeenCalledWith(expect.objectContaining({ page: 1, limit: 20 }));
  });

  it('GET /customers rejects a limit above 100', async () => {
    await request(app.getHttpServer()).get('/customers?limit=500').expect(400);
    expect(customersService.findAll).not.toHaveBeenCalled();
  });

  it('GET /customers/:id rejects a non-numeric id', async () => {
    await request(app.getHttpServer()).get('/customers/abc').expect(400);
  });

  it('POST /customers validates the body', async () => {
    const res = await request(app.getHttpServer())
      .post('/customers')
      .send({ name: '', email: 'not-an-email', countryCode: 'USA' })
      .expect(400);

    expect(res.body.message).toEqual(
      expect.arrayContaining(['email must be an email', 'name should not be empty']),
    );
  });
});

