import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { PaginationQueryDto } from '../common/pagination/pagination-query.dto';
import { Customer } from './customer.entity';
import { CustomersService } from './customers.service';

describe('CustomersService', () => {
  let service: CustomersService;
  const repository = {
    findAndCount: jest.fn(),
    findOne: jest.fn(),
    exists: jest.fn(),
    create: jest.fn((data: Partial<Customer>) => data),
    save: jest.fn(async (data: Partial<Customer>) => ({ id: 10, ...data })),
  };

  beforeEach(async () => {
    jest.clearAllMocks();
    const moduleRef = await Test.createTestingModule({
      providers: [CustomersService, { provide: getRepositoryToken(Customer), useValue: repository }],
    }).compile();

    service = moduleRef.get(CustomersService);
  });

  describe('findAll', () => {
    it('returns a paginated response', async () => {
      repository.findAndCount.mockResolvedValue([[{ id: 3 }, { id: 4 }], 42]);
      const query = Object.assign(new PaginationQueryDto(), { page: 2, limit: 2 });

      const result = await service.findAll(query);

      expect(repository.findAndCount).toHaveBeenCalledWith({ order: { id: 'ASC' }, skip: 2, take: 2 });
      expect(result).toEqual({
        data: [{ id: 3 }, { id: 4 }],
        meta: { page: 2, limit: 2, total: 42, totalPages: 21 },
      });
    });
  });

  describe('findOne', () => {
    it('returns the customer', async () => {
      repository.findOne.mockResolvedValue({ id: 1, name: 'Globex' });

      await expect(service.findOne(1)).resolves.toEqual({ id: 1, name: 'Globex' });
    });

    it('throws NotFoundException when missing', async () => {
