      ).rejects.toBeInstanceOf(ConflictException);
    });
  });
});

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Paginated, paginate } from '../common/pagination/paginated';
import { PaginationQueryDto } from '../common/pagination/pagination-query.dto';
import { Customer } from './customer.entity';
import { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomersService {
  constructor(
    @InjectRepository(Customer)
    private readonly customers: Repository<Customer>,
  ) {}

  async findAll(query: PaginationQueryDto): Promise<Paginated<Customer>> {
    const [data, total] = await this.customers.findAndCount({
      order: { id: 'ASC' },
      skip: (query.page - 1) * query.limit,
      take: query.limit,
    });
    return paginate(data, total, query.page, query.limit);
  }

  async findOne(id: number): Promise<Customer> {
    const customer = await this.customers.findOne({ where: { id } });
    if (!customer) {
      throw new NotFoundException(`Customer ${id} not found`);
    }
    return customer;
  }

  async create(dto: CreateCustomerDto): Promise<Customer> {
    const email = dto.email.toLowerCase();
    if (await this.customers.exists({ where: { email } })) {
      throw new ConflictException(`Customer with email ${email} already exists`);
    }
    const customer = this.customers.create({
      name: dto.name,
      email,
      countryCode: dto.countryCode.toUpperCase(),
    });
    return this.customers.save(customer);
  }
}

