import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';
import { Customer } from '../customers/customer.entity';

export enum InvoiceStatus {
  Draft = 'draft',
  Open = 'open',
  Paid = 'paid',
  Void = 'void',
}

@Entity({ name: 'invoices' })
@Index('idx_invoices_customer_issued', ['customerId', 'issuedAt'])
export class Invoice {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ length: 32, unique: true })
  number: string;

  @Column({ name: 'customer_id' })
