from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI(title="acme-ml", version="0.2.0")


class ChurnFeatures(BaseModel):
    months_active: int = Field(ge=0)
    seats: int = Field(ge=1)
    open_invoices: int = Field(ge=0)
    support_tickets_90d: int = Field(ge=0)


class ChurnScore(BaseModel):
    score: float
    risk: str


def score_churn(features: ChurnFeatures) -> float:
    raw = (
        0.35
        - min(features.months_active, 36) * 0.008
        - min(features.seats, 50) * 0.003
        + features.open_invoices * 0.08
        + features.support_tickets_90d * 0.02
    )
    return round(max(0.0, min(1.0, raw)), 3)


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


@app.post("/v1/churn-score", response_model=ChurnScore)
def churn_score(features: ChurnFeatures) -> ChurnScore:
    score = score_churn(features)
    risk = "high" if score >= 0.6 else "medium" if score >= 0.3 else "low"
    return ChurnScore(score=score, risk=risk)

