import { useState } from 'react';
import { CartSummary } from './components/CartSummary';
import { CheckoutForm, type CheckoutDetails } from './components/CheckoutForm';
import { Header } from './components/Header';
import type { CartItem } from './types';

const initialCart: CartItem[] = [
  { id: 'mug', name: 'Ceramic mug', unitPriceCents: 1200, quantity: 2 },
  { id: 'tea', name: 'Green tea', unitPriceCents: 850, quantity: 1 },
];

export default function App() {
  const [submitting, setSubmitting] = useState(false);
  const [confirmation, setConfirmation] = useState<string | null>(null);
  const itemCount = initialCart.reduce((sum, item) => sum + item.quantity, 0);

  async function handleCheckout(details: CheckoutDetails) {
    setSubmitting(true);
    await new Promise((resolve) => setTimeout(resolve, 500));
    setSubmitting(false);
    setConfirmation(`Thanks, ${details.fullName}! A receipt is on its way to ${details.email}.`);
  }

  return (
    <>
      <Header itemCount={itemCount} />
      <div className="layout">
        <section>
          <h1>Checkout</h1>
          {confirmation ? (
            <p role="status">{confirmation}</p>
          ) : (
            <CheckoutForm onSubmit={handleCheckout} submitting={submitting} />
          )}
        </section>
        <CartSummary items={initialCart} shippingCents={500} />
      </div>
    </>
  );
}

