import type { CartItem } from '../types';
import { formatCents } from '../utils/currency';

interface CartSummaryProps {
  items: CartItem[];
  shippingCents?: number;
}

export function CartSummary({ items, shippingCents = 0 }: CartSummaryProps) {
  const subtotal = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
  const total = subtotal + shippingCents;

  if (items.length === 0) {
    return <aside className="cart-summary">Your cart is empty.</aside>;
  }

  return (
    <aside className="cart-summary" aria-label="Order summary">
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            <span>{`${item.name} x ${item.quantity}`}</span>
            <span>{formatCents(item.unitPriceCents * item.quantity)}</span>
          </li>
        ))}
      </ul>
      <dl>
        <dt>Subtotal</dt>
        <dd>{formatCents(subtotal)}</dd>
        <dt>Shipping</dt>
        <dd>{shippingCents === 0 ? 'Free' : formatCents(shippingCents)}</dd>
        <dt>Total</dt>
        <dd data-testid="cart-total">{formatCents(total)}</dd>
      </dl>
    </aside>
  );
}

