import type { FormEvent } from 'react';

export interface CheckoutDetails {
  email: string;
  fullName: string;
  address: string;
  postalCode: string;
}

interface CheckoutFormProps {
  onSubmit: (details: CheckoutDetails) => void;
  submitting?: boolean;
