import { asc, eq, ilike } from 'drizzle-orm';
import type { FastifyPluginAsync } from 'fastify';
import type { Database } from '../db/client.js';
import { products } from '../db/schema.js';

interface ProductRoutesOptions {
  db: Database;
}

interface ListQuery {
  q?: string;
  limit: number;
  offset: number;
}

const listQuerySchema = {
  type: 'object',
  properties: {
    q: { type: 'string', minLength: 1, maxLength: 100 },
    limit: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
    offset: { type: 'integer', minimum: 0, default: 0 },
  },
  additionalProperties: false,
} as const;

const createBodySchema = {
  type: 'object',
  required: ['sku', 'name', 'priceCents'],
  properties: {
    sku: { type: 'string', minLength: 1, maxLength: 64 },
    name: { type: 'string', minLength: 1, maxLength: 255 },
    description: { type: 'string' },
    priceCents: { type: 'integer', minimum: 0 },
    categoryId: { type: 'integer', minimum: 1 },
  },
  additionalProperties: false,
} as const;

export const productRoutes: FastifyPluginAsync<ProductRoutesOptions> = async (app, { db }) => {
  app.get<{ Querystring: ListQuery }>(
    '/',
    { schema: { querystring: listQuerySchema } },
    async (request) => {
      const { q, limit, offset } = request.query;
      const where = q ? ilike(products.name, '%' + q + '%') : undefined;

      const items = await db
        .select()
        .from(products)
        .where(where)
        .orderBy(asc(products.id))
        .limit(limit)
        .offset(offset);

      return { items, limit, offset };
    },
  );

  app.get<{ Params: { id: number } }>(
    '/:id',
    {
      schema: {
        params: {
          type: 'object',
          properties: { id: { type: 'integer', minimum: 1 } },
          required: ['id'],
        },
      },
    },
    async (request, reply) => {
      const [product] = await db.select().from(products).where(eq(products.id, request.params.id));
      if (!product) {
        return reply.code(404).send({ message: `Product ${request.params.id} not found` });
      }
      return product;
    },
  );

  app.post<{
    Body: { sku: string; name: string; description?: string; priceCents: number; categoryId?: number };
  }>('/', { schema: { body: createBodySchema } }, async (request, reply) => {
    const [created] = await db.insert(products).values(request.body).returning();
    return reply.code(201).send(created);
  });
};

