import type { FastifyInstance } from 'fastify';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { buildApp } from '../src/app.js';
import { categories, products } from '../src/db/schema.js';
import { startTestDatabase, type TestDatabase } from './support/postgres.js';

let testDb: TestDatabase;
let app: FastifyInstance;

beforeAll(async () => {
  testDb = await startTestDatabase();
  const [kitchen] = await testDb.db
    .insert(categories)
    .values({ name: 'Kitchen', slug: 'kitchen' })
    .returning();
  await testDb.db.insert(products).values([
    { sku: 'MUG-001', name: 'Ceramic Mug', priceCents: 1200, categoryId: kitchen.id },
    { sku: 'MUG-002', name: 'Travel mug, insulated', priceCents: 2400, categoryId: kitchen.id },
    { sku: 'KTL-001', name: 'Electric Kettle', priceCents: 3900, categoryId: kitchen.id },
    { sku: 'LMP-001', name: 'Desk Lamp', priceCents: 4500 },
  ]);
  app = buildApp(testDb.db);
  await app.ready();
});

afterAll(async () => {
  await app?.close();
  await testDb?.stop();
});

describe('GET /products', () => {
  it('lists products ordered by id', async () => {
    const res = await app.inject({ method: 'GET', url: '/products' });

    expect(res.statusCode).toBe(200);
    const body = res.json();
    expect(body.items.map((p: { sku: string }) => p.sku)).toEqual([
      'MUG-001',
      'MUG-002',
      'KTL-001',
      'LMP-001',
    ]);
    expect(body).toMatchObject({ limit: 20, offset: 0 });
  });

  it('filters by name case-insensitively with q', async () => {
    const res = await app.inject({ method: 'GET', url: '/products?q=MUG' });

    expect(res.statusCode).toBe(200);
    expect(res.json().items.map((p: { name: string }) => p.name)).toEqual([
      'Ceramic Mug',
      'Travel mug, insulated',
    ]);
  });

  it('matches substrings in the middle of the name', async () => {
    const res = await app.inject({ method: 'GET', url: '/products?q=ettl' });

    expect(res.json().items).toHaveLength(1);
    expect(res.json().items[0].sku).toBe('KTL-001');
  });

  it('paginates with limit and offset', async () => {
    const res = await app.inject({ method: 'GET', url: '/products?limit=2&offset=2' });

    expect(res.json().items.map((p: { sku: string }) => p.sku)).toEqual(['KTL-001', 'LMP-001']);
  });

  it('rejects an invalid limit', async () => {
    const res = await app.inject({ method: 'GET', url: '/products?limit=0' });

    expect(res.statusCode).toBe(400);
  });
});

describe('GET /products/:id', () => {
  it('returns 404 for a missing product', async () => {
    const res = await app.inject({ method: 'GET', url: '/products/99999' });

    expect(res.statusCode).toBe(404);
  });
});

describe('POST /products', () => {
  it('creates a product', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/products',
      payload: { sku: 'TEA-001', name: 'Loose Leaf Tea', priceCents: 900 },
    });

    expect(res.statusCode).toBe(201);
    expect(res.json()).toMatchObject({ sku: 'TEA-001', name: 'Loose Leaf Tea' });
  });
});

